const lmMinTagCoverage = 0.50
type layoutFit struct { TagCoverage, Score, TagScore, RunnerUpScore, Margin, Threshold float64; SiteTermCount int; MatchedTerms, UnmatchedTerms []string; RunnerUp string }
func (r *layoutResolution) LibraryGap() bool { return r.IsFallback || r.IsSchemeMismatch || r.IsWeakFit }
func (r *layoutResolution) GapReason() string // fallback > scheme_mismatch > weak_tag_fit

func lmBuildFit(best *scoredLayout, scored []scoredLayout, siteTerms map[string]struct{}, weight func(string) float64) layoutFit {
  for term := range siteTerms { totalWeight += weight(term); if _, ok := winnerTags[term]; ok { matched } else { unmatched } }
  if totalWeight > 0 { fit.TagCoverage = best.tagScore / totalWeight }
}

if resolution.LibraryGap() {
  if resolution.IsWeakFit && !resolution.IsFallback && !resolution.IsSchemeMismatch { logger.Warn("weak tag fit ...", zap.Float64("tag_coverage", ...), zap.Strings("unmatched_terms", ...)) }
  ...
}
source := "library_match"; if resolution.IsFallback { source = "library_fallback" }

if coverage, ok := readFloatFromContext(collectedData, "composition_layout.tag_coverage"); ok {
  lineage["layout_match_score"] = coverage
  lineage["layout_fit"] = map[string]interface{}{"tag_coverage":..., "matched_terms":..., "unmatched_terms":..., "threshold":..., "runner_up":...}
}

switch reported := readStringFromContext(collectedData, "composition_layout.source"); reported {
case "theme_kit_default", "library_fallback", "library_match", "mission_hint": layoutSource = reported
default: if readBoolFromContext(..., "composition_layout.is_fallback") { layoutSource = "library_fallback" } }
if readBoolFromContext(..., "composition_layout.is_scheme_mismatch") { lineage["layout_scheme_mismatch"] = true }
